Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Import ListNotations.
Import ITree.Exc.
Open Scope Z_scope.
Open Scope mspec_scope.

Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Local Ltac transport_after_call segs m m' MU WM ::= transport_after_call_fast segs m m' MU WM.
Local Ltac lia ::= lia3.
Notation z64 := (Z_to_bv 64 0) (only parsing).
Ltac zs := zstep; try (fix_litstore; mem_after_store_opt).
Ltac fix_ret := lazymatch goal with |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
  replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]) end.

Definition gfile_cells (flags : word) (rpos rend close wend wpos wbase writefn seekfn buf bufsize fd : Z) (mode lock : word) (lbf : Z) : list cell := ltac2:(Rpl.RP.run_k (rplG ()) 15 "U5;A1;o1;Y6;00;A1;i0;#0;A2;k6;#0;o7;A1;o5;#2;A1;o8;#2;Lflags;R#1;Lrpos;Ri2;Lrend;Ri2;Lclose;Ri2;Lwend;Ri2;Lwpos;Ri2;Lwbase;Ri2;Lwritefn;Ri2;Lseekfn;Ri2;Lbuf;Ri2;Lbufsize;Ri2;Lfd;Ri2;Lmode;R#1;Llock;R#1;Llbf;Ri2;A3;o3;i4;A1;o5;r15;A3;o3;i4;#3;A3;o3;i4;A1;o8;A2;k6;#0;r14;A3;o3;i4;A1;o8;A2;k6;#0;r13;A3;o3;i4;A1;o8;A2;k6;#0;r12;A3;o3;i4;A1;o8;A2;k6;#0;r11;A3;o3;i4;A1;o8;A2;k6;#0;r10;A3;o3;i4;#4;A3;o3;i4;A1;o8;A2;k6;#0;r9;A3;o3;i4;#4;A3;o3;i4;A1;o8;A2;k6;#0;r8;A3;o3;i4;A1;o8;A2;k6;#0;r7;A3;o3;i4;A1;o8;A2;k6;#0;r6;A3;o3;i4;A1;o8;A2;k6;#0;r5;A3;o3;i4;#4;A3;o3;i4;#4;A3;o3;i4;A1;o5;A2;k6;#0;r4;A3;o3;i4;#3;A3;o3;i4;#4;A3;o3;i4;A1;o5;r3;A3;o3;i4;A1;o5;r2;A3;o3;i4;A1;o5;A2;k6;#0;r1;A1;o9;i4;").

Lemma file_cells_g : forall flags wend wpos wbase writefn buf bufsize fd mode lbf tail,
  file_cells flags wend wpos wbase writefn buf bufsize fd mode lbf tail
  = gfile_cells flags 0 0 0x17738 wend wpos wbase writefn 0x178f4 buf bufsize fd mode (Z_to_bv 64 0xffffffff) lbf ++ [C4 z64; CB 80 tail].
